/** 이번 주 체크 (SRS-PRO-002): the weekly patient check, when switched on in Settings. Own items, not a validated scale. */
import { useState } from 'preact/hooks';
import { FEATURES } from '../../config';
import { actions, useApp } from '../../data/store';
import { checkinAdvice, isComplete, visibleQuestions, type CheckinAnswers } from '../../rehab/checkin';
import { AppBar, Notice } from '../components/common';
import { navigate } from '../router';

export function Checkin() {
  const { profile } = useApp();
  const [a, setA] = useState<CheckinAnswers>({});
  const [saved, setSaved] = useState(false);
  if (FEATURES.rehab === 'off' || !profile?.checkin?.enabled) {
    return (
      <>
        <AppBar title="이번 주 체크" onBack />
        <main class="main">
          <div class="card">
            <p class="small ink2">체크 설문이 꺼져 있습니다. 설정 › 환자 설문에서 켤 수 있습니다.</p>
          </div>
        </main>
      </>
    );
  }
  const set = (id: string, v: string | string[] | number) => setA({ ...a, [id]: v });
  const qs = visibleQuestions(a);
  const answered = qs.filter((q) => q.kind === 'multi' || a[q.id] !== undefined).length;
  return (
    <>
      <AppBar title="이번 주 체크" sub="약 1분 · 앱 자체 문항(검증된 척도 아님)" onBack />
      <main class="main">
        {saved ? (
          <div class="card accent">
            <h3>기록했습니다</h3>
            <p class="small ink2">의료진용 요약에 최근 체크가 함께 나옵니다. 다음 체크는 일주일 뒤입니다.</p>
            {checkinAdvice(a).map((x) => (
              <Notice tone={x.tone}>
                <span class="small">
                  {x.text}
                  {x.href && (
                    <>
                      {' '}
                      <a href={x.href}>{x.cta} ›</a>
                    </>
                  )}
                </span>
              </Notice>
            ))}
            <button class="btn primary block" onClick={() => navigate('/')}>
              홈으로
            </button>
          </div>
        ) : (
          <>
            {qs.map((q, k) => (
              <div class="card">
                <h3>
                  {k + 1}. {q.text}
                </h3>
                {q.kind === 'single' &&
                  q.options!.map((o) => (
                    <label class="check">
                      <input
                        type="radio"
                        id={`chk-${q.id}-${o.value}`}
                        name={q.id}
                        checked={a[q.id] === o.value}
                        onChange={() => set(q.id, o.value)}
                      />
                      <span>{o.label}</span>
                    </label>
                  ))}
                {q.kind === 'multi' &&
                  q.options!.map((o) => {
                    const cur = Array.isArray(a[q.id]) ? (a[q.id] as string[]) : [];
                    return (
                      <label class="check">
                        <input
                          type="checkbox"
                          id={`chk-${q.id}-${o.value}`}
                          checked={cur.includes(o.value)}
                          onChange={(e) =>
                            set(q.id, (e.target as HTMLInputElement).checked ? [...cur, o.value] : cur.filter((x) => x !== o.value))
                          }
                        />
                        <span>{o.label}</span>
                      </label>
                    );
                  })}
                {q.kind === 'scale' && (
                  <div class="stack">
                    {/* Eleven taps rather than a slider: 0 is an answer too, and a slider shows 0 before anything is chosen. */}
                    <div class="seg nrs" role="group" aria-label={`${q.text} 0(${q.minLabel})부터 10(${q.maxLabel})까지`}>
                      {Array.from({ length: 11 }, (_, v) => (
                        <button type="button" id={`chk-${q.id}-${v}`} aria-pressed={a[q.id] === v} onClick={() => set(q.id, v)}>
                          {v}
                        </button>
                      ))}
                    </div>
                    <div class="row between xsmall muted">
                      <span>0 {q.minLabel}</span>
                      <span>10 {q.maxLabel}</span>
                    </div>
                  </div>
                )}
              </div>
            ))}
            <Notice tone="info">
              <span class="small">답은 이 기기에만 저장되고, 직접 내보내거나 진료 때 보여 줄 때만 다른 사람이 봅니다.</span>
            </Notice>
            <button
              class="btn primary block"
              disabled={!isComplete(a)}
              onClick={async () => {
                await actions.addCheckin(a);
                setSaved(true);
              }}
            >
              {isComplete(a) ? '기록하기' : `모두 답해 주세요 (${answered}/${qs.length})`}
            </button>
          </>
        )}
      </main>
    </>
  );
}
